const { DatabaseSync } = require('node:sqlite');
const crypto = require('crypto');

const DB_PATH = '/home/node/.n8n/auth.db';
const MAX_ATTEMPTS = 10;
const WINDOW_MS = 15 * 60 * 1000;
const BLOCK_MS = 15 * 60 * 1000;

const db = new DatabaseSync(DB_PATH);
db.exec('PRAGMA journal_mode=WAL');
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    username TEXT UNIQUE NOT NULL,
    email TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    token TEXT,
    createdAt TEXT NOT NULL,
    lastLogin TEXT,
    gdpr_consent INTEGER DEFAULT 1,
    active INTEGER DEFAULT 1
  )
`);
db.exec(`
  CREATE TABLE IF NOT EXISTS audit_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    timestamp TEXT NOT NULL,
    action TEXT NOT NULL,
    username TEXT,
    status TEXT NOT NULL,
    detail TEXT
  )
`);
db.exec(`
  CREATE TABLE IF NOT EXISTS rate_limits (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    key_text TEXT NOT NULL,
    timestamp INTEGER NOT NULL,
    type TEXT NOT NULL DEFAULT 'attempt'
  )
`);
db.exec(`
  CREATE INDEX IF NOT EXISTS idx_rate_limits_key ON rate_limits(key_text, timestamp)
`);

function hashPassword(password) {
  return crypto.createHash('sha256').update(password.trim()).digest('hex');
}

function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

function logAudit(action, username, status, detail) {
  const stmt = db.prepare('INSERT INTO audit_logs (timestamp, action, username, status, detail) VALUES (?, ?, ?, ?, ?)');
  stmt.run(new Date().toISOString(), action, username || 'unknown', status, detail);
}

function cleanExpiredRateLimits() {
  const cutoff = Date.now() - WINDOW_MS;
  db.prepare('DELETE FROM rate_limits WHERE timestamp < ?').run(cutoff);
}

function getRecentAttempts(key) {
  const cutoff = Date.now() - WINDOW_MS;
  const rows = db.prepare("SELECT COUNT(*) as count FROM rate_limits WHERE key_text = ? AND timestamp > ? AND type = 'attempt'").get(key, cutoff);
  return rows.count;
}

function isBlocked(key) {
  const cutoff = Date.now() - BLOCK_MS;
  const rows = db.prepare("SELECT COUNT(*) as count FROM rate_limits WHERE key_text = ? AND timestamp > ? AND type = 'block'").get(key, cutoff);
  return rows.count > 0;
}

function checkRateLimit(username) {
  cleanExpiredRateLimits();
  const key = username.toLowerCase();
  if (isBlocked(key)) {
    const blockTime = db.prepare("SELECT MAX(timestamp) as t FROM rate_limits WHERE key_text = ? AND type = 'block'").get(key);
    const remaining = Math.ceil((blockTime.t + BLOCK_MS - Date.now()) / 60000);
    return { blocked: true, remainingMinutes: remaining };
  }
  const attempts = getRecentAttempts(key);
  return { blocked: false, attempts };
}

function recordFailed(username) {
  const key = username.toLowerCase();
  db.prepare("INSERT INTO rate_limits (key_text, timestamp, type) VALUES (?, ?, 'attempt')").run(key, Date.now());
  cleanExpiredRateLimits();
  if (getRecentAttempts(key) >= MAX_ATTEMPTS) {
    db.prepare("INSERT INTO rate_limits (key_text, timestamp, type) VALUES (?, ?, 'block')").run(key, Date.now());
  }
}

function clearRateLimit(username) {
  const key = username.toLowerCase();
  db.prepare("DELETE FROM rate_limits WHERE key_text = ?").run(key);
}

const input = $input.first().json;
const parts = input.query.split(',').map(p => p.trim());
const action = parts[0];

// --- CHECK USER ---
if (action === 'check_user') {
  const username = parts[1];
  if (!username) return [{ json: { response: 'ERROR: username required' } }];
  const user = db.prepare('SELECT id, username FROM users WHERE LOWER(username) = LOWER(?)').get(username);
  logAudit('check_user', username, user ? 'exists' : 'not_exists', '');
  return [{ json: { response: user ? 'EXISTS' : 'NOT_EXISTS' } }];
}

// --- REGISTER ---
if (action === 'register') {
  const username = parts[1];
  const email = parts[2];
  const password = parts[3];

  if (!username || !email || !password) {
    logAudit('register', username, 'error', 'missing fields');
    return [{ json: { response: 'ERROR: missing fields' } }];
  }
  if (!/^[a-zA-Z0-9_]{3,20}$/.test(username.trim())) {
    logAudit('register', username, 'error', 'invalid username');
    return [{ json: { response: 'ERROR: username must be 3-20 alphanumeric characters' } }];
  }
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    logAudit('register', username, 'error', 'invalid email');
    return [{ json: { response: 'ERROR: invalid email' } }];
  }
  if (!password || password.trim().length < 6) {
    logAudit('register', username, 'error', 'weak password');
    return [{ json: { response: 'ERROR: password must be at least 6 characters' } }];
  }

  const existing = db.prepare('SELECT id FROM users WHERE LOWER(username) = LOWER(?) OR LOWER(email) = LOWER(?)').get(username, email);
  if (existing) {
    const conflict = db.prepare('SELECT username, email FROM users WHERE id = ?').get(existing.id);
    if (conflict.username.toLowerCase() === username.toLowerCase()) {
      logAudit('register', username, 'error', 'username taken');
      return [{ json: { response: 'ERROR: username already taken' } }];
    }
    logAudit('register', username, 'error', 'email taken');
    return [{ json: { response: 'ERROR: email already registered' } }];
  }

  const id = crypto.randomUUID();
  const now = new Date().toISOString();
  db.prepare('INSERT INTO users (id, username, email, password, token, createdAt, lastLogin, gdpr_consent, active) VALUES (?, ?, ?, ?, NULL, ?, NULL, 1, 1)').run(
    id, username.trim(), email.trim().toLowerCase(), hashPassword(password), now
  );

  const registerToken = generateToken();
  db.prepare('UPDATE users SET token = ?, lastLogin = ? WHERE id = ?').run(registerToken, now, id);
  logAudit('register', username, 'success', 'account created');

  try {
    const USERS_FILE = '/home/node/.n8n/users.json';
    let usersData = { users: [] };
    if (fs.existsSync(USERS_FILE)) usersData = JSON.parse(fs.readFileSync(USERS_FILE, 'utf8'));
    usersData.users.push({ id, username: username.trim(), email: email.trim().toLowerCase(), password: hashPassword(password), createdAt: now, gdpr_consent: 1, active: true });
    fs.writeFileSync(USERS_FILE, JSON.stringify(usersData, null, 2));
  } catch(e) {}

  return [{
    json: {
      response: 'SUCCESS: Account created for ' + username.trim(),
      userId: id,
      token: registerToken
    }
  }];
}

// --- LOGIN ---
if (action === 'login') {
  const username = parts[1];
  const password = parts[2];

  if (!username || !password) {
    logAudit('login', username || 'unknown', 'error', 'missing fields');
    return [{ json: { response: 'ERROR: username and password required' } }];
  }

  const rateCheck = checkRateLimit(username);
  if (rateCheck.blocked) {
    logAudit('login', username, 'blocked', 'rate limited ' + rateCheck.remainingMinutes + 'min');
    return [{ json: { response: 'ERROR: Too many attempts. Try again in ' + rateCheck.remainingMinutes + ' minute(s).' } }];
  }

  const user = db.prepare('SELECT * FROM users WHERE LOWER(username) = LOWER(?)').get(username);
  if (!user) {
    recordFailed(username);
    logAudit('login', username, 'error', 'not found');
    return [{ json: { response: 'ERROR: account not found' } }];
  }
  if (!user.active) {
    logAudit('login', username, 'error', 'deactivated');
    return [{ json: { response: 'ERROR: account deactivated' } }];
  }
  if (user.password !== hashPassword(password)) {
    recordFailed(username);
    logAudit('login', username, 'error', 'wrong password');
    return [{ json: { response: 'ERROR: incorrect password' } }];
  }

  const sessionToken = generateToken();
  const now = new Date().toISOString();
  db.prepare('UPDATE users SET token = ?, lastLogin = ? WHERE id = ?').run(sessionToken, now, user.id);
  clearRateLimit(username);
  logAudit('login', username, 'success', 'authenticated');

  return [{
    json: {
      response: 'SUCCESS: Welcome back ' + user.username,
      userId: user.id,
      token: sessionToken,
      user: { id: user.id, username: user.username, email: user.email }
    }
  }];
}

// --- CHECK SESSION ---
if (action === 'check_session') {
  const token = parts[1];
  if (!token) return [{ json: { valid: false, response: 'ERROR: no token' } }];
  const user = db.prepare('SELECT id, username, email FROM users WHERE token = ? AND active = 1').get(token);
  if (!user) return [{ json: { valid: false, response: 'ERROR: session invalid' } }];
  return [{ json: { valid: true, response: 'Session valid for ' + user.username, user } }];
}

// --- LOGOUT ---
if (action === 'logout') {
  const token = parts[1];
  if (!token) return [{ json: { response: 'ERROR: no token' } }];
  const user = db.prepare('SELECT username FROM users WHERE token = ?').get(token);
  if (user) {
    db.prepare('UPDATE users SET token = NULL WHERE token = ?').run(token);
    logAudit('logout', user.username, 'success', 'logged out');
  }
  return [{ json: { response: 'SUCCESS: logged out' } }];
}

// --- DELETE ACCOUNT ---
if (action === 'delete_account') {
  const token = parts[1];
  if (!token) return [{ json: { response: 'ERROR: no token' } }];
  const user = db.prepare('SELECT id, username FROM users WHERE token = ?').get(token);
  if (!user) return [{ json: { response: 'ERROR: invalid session' } }];
  db.prepare('UPDATE users SET active = 0, token = NULL WHERE id = ?').run(user.id);
  logAudit('delete_account', user.username, 'success', 'account deactivated');
  return [{ json: { response: 'SUCCESS: Account ' + user.username + ' has been deleted' } }];
}


// --- EXPORT DATA (RGPD - Portabilité) ---
if (action === 'export_data') {
  const token = parts[1];
  if (!token) return [{ json: { response: 'ERROR: no token' } }];
  const user = db.prepare('SELECT id, username, email, createdAt, lastLogin, gdpr_consent, active FROM users WHERE token = ? AND active = 1').get(token);
  if (!user) return [{ json: { response: 'ERROR: invalid session' } }];

  // Also fetch preferences if they exist
  let preferences = null;
  try {
    const fs = require('fs');
    const prefsPath = '/home/node/.n8n/preferences.json';
    if (fs.existsSync(prefsPath)) {
      const prefsData = JSON.parse(fs.readFileSync(prefsPath, 'utf8'));
      preferences = (prefsData.preferences || []).find(p => p.userId === user.id) || null;
    }
  } catch(e) {}

  return [{
    json: {
      response: 'SUCCESS: Data exported',
      data: {
        account: {
          id: user.id,
          username: user.username,
          email: user.email,
          createdAt: user.createdAt,
          lastLogin: user.lastLogin,
          gdprConsent: !!user.gdpr_consent,
          active: !!user.active
        },
        preferences: preferences ? {
          topics: preferences.topics,
          email: preferences.email,
          scheduleTime: preferences.scheduleTime,
          timezone: preferences.timezone,
          articleCount: preferences.articleCount,
          frequency: preferences.frequency,
          sources: preferences.sources,
          emailFormat: preferences.emailFormat,
          customPrompt: preferences.customPrompt,
          active: preferences.active
        } : null,
        exportedAt: new Date().toISOString()
      }
    }
  }];
}

return [{ json: { response: 'ERROR: unknown action' } }];
